SUPPORT_SOURCES={
 ('meshtastic/firmware','lilygo-t-beam-supreme'):'https://meshtastic.org/docs/hardware/devices/lilygo/tbeam/',
 ('meshtastic/firmware','lilygo-t3s3-v1-0'):'https://meshtastic.org/docs/hardware/devices/lilygo/lora/',
 ('meshtastic/firmware','lilygo-t-watch-s3'):'https://meshtastic.org/docs/hardware/devices/lilygo/twatch/',
}

def main():
 evidence=_read(ROOT/'data/collection/repository-evidence.json',{})
 records=[];reviews={}
 available_devices={frontmatter(path).get('id') for path in (ROOT/'content/devices').rglob('*.md')}
 extra_relations=_read(ROOT/'data/collection/reviewed-device-relations.json',[])
 for repo,id,name,tags,zh,en,ja,devices,state in PROFILES:
  e=evidence.get(repo.lower(),{})
  if e.get('status')!='verified':continue
  devices=list(devices);extra_sources={}
  for relation in extra_relations:
   if relation['projectId']==id and relation['deviceId'] in available_devices and relation['deviceId'] not in devices:
    devices.append(relation['deviceId']);extra_sources[relation['deviceId']]=relation['sourceUrl']
  canonical=e['repository'];url='https://github.com/'+canonical
  data=dict(id=id,name=name,repository=url,license=e.get('verifiedLicense') or (e.get('license') or {}).get('spdx_id'),summary=dict(zh=zh,en=en,ja=ja),kind='firmware',tags=tags,devices=[dict(deviceId=d,sourceUrl=SUPPORT_SOURCES.get((repo.lower(),d),extra_sources.get(d,url+'#readme'))) for d in devices],compatibility=state,addedAt='2026-10-16',sources=[dict(url=url+'#readme',checkedAt=e['readmeCheckedAt'])])
  if e.get('verifiedLicense') and e.get('licenseReview'):
   data['sources'].append(dict(url=e['licenseReview']['sourceUrl'],checkedAt=e['licenseReview']['checkedAt']))
  if id=='meshtastic':
   hardware=_read(ROOT/'data/collection/meshtastic-hardware-review.json',{})
   data['sources'] += [dict(url=r['url'],checkedAt=r['checkedAt']) for key,r in hardware.items() if key in {'tbeam','lora','twatch','tdeck'}]
  if id in ['esp-idf','esphome','micropython']:data['kind']='framework'
  if id in ['tinydraw','lvgl-watchfaces','beryllium-micro']:data['kind']='application'
  if id in ['m5ez','sd-updater','pngle','esp-hal','esp32drop']:data['kind']='library'
  if id in ['microhydra-apps','m5-lvgl-emulator']:data['kind']='application'
  if id in ['stackchan-bsp','m5-onscreen-keyboard']:data['kind']='library'
  note='Short editorial summary based on the upstream README. Hardware support is documented upstream; no device testing was performed by esp32.sh.'
  if id=='readpaper':note+='\n\nThis listing covers the open-source firmware and repository contents. Upstream states that the separate browser extension is closed-source from version 2.0 onward; older extension sources in this repository retain Apache-2.0.'
  records.append(dict(kind='project',data=data,note=note))
  reviews[repo.lower()]={'contentId':id,'review':'Summary reviewed against cached upstream README and linked official hardware documentation; only explicitly named models linked.','readmeCheckedAt':e['readmeCheckedAt'],'deviceIds':devices,'compatibility':state,'supportSources':[d['sourceUrl'] for d in data['devices']]}
 _write(ROOT/'data/collection/reviewed-projects.json',records)
 _write(ROOT/'data/collection/project-editorial-review.json',reviews)
 print('Reviewed project records:',len(records))
if __name__=='__main__':main()
